SINA_SMART["anat1-respiratory"] = {"lecture":"anat1-respiratory","title":"Thorax part 8: lungs and respiratory system","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-respiratory:e0","text":"Pulmonary vessels: gas exchange; bronchial vessels: nourish lung tissue.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-respiratory:e1","text":"Parasympathetic → bronchoconstriction.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-respiratory:e2","text":"Trachea bifurcates at T4-T5.","topic":"Trachea and bronchi","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-respiratory:e3","text":"Right main bronchus: 3 lobar bronchi; left: 2.","topic":"Trachea and bronchi","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-respiratory:e4","text":"Segmental bronchi → bronchioles → alveolar sacs.","topic":"Trachea and bronchi","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-respiratory:e5","text":"Lung: base, apex above rib 1, costal and mediastinal surfaces, hilum.","topic":"Lungs: shape, surfaces and lobes","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-respiratory:e6","text":"Root: bronchus, pulmonary artery and veins, nerves, lymphatics.","topic":"Lungs: shape, surfaces and lobes","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-respiratory:e7","text":"Right lung: 3 lobes, oblique + horizontal fissures.","topic":"Lungs: shape, surfaces and lobes","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-respiratory:e8","text":"Left lung: 2 lobes, oblique fissure, cardiac notch, lingula.","topic":"Lungs: shape, surfaces and lobes","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1nuy7hi":"a","cr1p81":"a","1olllac":"a","1hi948g":"a","fzmgf1":"a","1gkrma7":"a","dtb3fn":"a","1co191v":"a","11qhl8h":"a","1cw4mhm":"a"},"mapCounts":{"verified":0,"auto":10,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-respiratory:e0":{"s":0,"u":["Pulmonary vessels: gas exchange; bronchial vessels: nourish lung tissue.","The pulmonary circulation brings deoxygenated blood to the respiratory tissue (pulmonary arteries from the right ventricle; oxygenated blood returns in the pulmonary veins to the left atrium), while bronchial vessels nourish the non-respiratory tissue with oxygenated blood.","The lungs , organs of gas exchange, lie on each side of the mediastinum in the pleural cavities, attached to the trachea and heart by their roots."],"dp":[{"h":"Note","t":"Two circulations : pulmonary arteries carry deoxygenated blood for gas exchange; bronchial arteries (from the aorta) nourish lung tissue."}]},"anat1-respiratory:e1":{"s":0,"u":["Parasympathetic → bronchoconstriction.","Parasympathetic innervation causes bronchoconstriction ."],"dp":[{"h":"Note","t":"Parasympathetic (vagus) → bronchoconstriction ; sympathetic → bronchodilation (the basis of β₂-agonist inhalers in asthma)."}]},"anat1-respiratory:e2":{"s":1,"u":["Trachea bifurcates at T4-T5.","The trachea runs from the larynx into the thorax and bifurcates into the right and left main bronchi at T4-T5 ."],"dp":[]},"anat1-respiratory:e3":{"s":1,"u":["Right main bronchus: 3 lobar bronchi; left: 2.","The right main bronchus gives three lobar (secondary) bronchi (superior, middle, inferior); the left gives two .","The trachea runs from the larynx into the thorax and bifurcates into the right and left main bronchi at T4-T5 ."],"dp":[{"h":"Why inhaled objects go to the right lung","t":"The right main bronchus is wider, shorter and more vertical than the left, which is pushed sideways by the heart and aortic arch. A peanut or tooth inhaled by accident therefore usually drops into the right bronchus, and aspiration pneumonia most often affects the right lower lobe. Source: the lecture's trachea and bronchi section (clinical application)."},{"h":"Clinical","t":"The right main bronchus is shorter, wider and more vertical → inhaled foreign bodies and aspirated material usually go to the right lung."},{"h":"Note","t":"Trachea bifurcates at T4/T5 (sternal angle); right main bronchus → 3 lobar bronchi, left → 2; then segmental (bronchopulmonary segments are the surgical units)."}]},"anat1-respiratory:e4":{"s":1,"u":["Segmental bronchi → bronchioles → alveolar sacs.","Each lobar bronchus divides into segmental (tertiary) bronchi, then bronchioles ending in alveolar sacs ."],"dp":[]},"anat1-respiratory:e5":{"s":2,"u":["Lung: base, apex above rib 1, costal and mediastinal surfaces, hilum.","Each lung is a half-cone with a base on the diaphragm, an apex rising above rib 1 into the neck (crossed in front by the subclavian artery and vein), a costal surface against the ribs, a mediastinal surface with the hilum , and three borders (sharp inferior and anterior, rounded posterior)."],"dp":[]},"anat1-respiratory:e6":{"s":2,"u":["Root: bronchus, pulmonary artery and veins, nerves, lymphatics.","The root (main bronchus, pulmonary artery and veins, nerves, lymphatics) is sleeved by mediastinal pleura reflecting into visceral pleura; the outlined area is the hilum ."],"dp":[{"h":"Note","t":"Hilum contents: main bronchus, pulmonary artery, 2 pulmonary veins, bronchial vessels, nerves, lymphatics. On the left the artery is highest ; on the right the bronchus is often highest (eparterial bronchus)."}]},"anat1-respiratory:e7":{"s":2,"u":["Right lung: 3 lobes, oblique + horizontal fissures.","Right lung : three lobes (superior, middle, inferior) separated by the oblique and horizontal fissures; shorter and wider because the right dome is higher, but slightly larger overall.","Left lung : two lobes (superior, inferior) separated by the oblique fissure (along rib 6); instead of a middle lobe it has the cardiac notch and the lingula , an extension of the superior lobe."],"dp":[]},"anat1-respiratory:e8":{"s":2,"u":["Left lung: 2 lobes, oblique fissure, cardiac notch, lingula.","Left lung : two lobes (superior, inferior) separated by the oblique fissure (along rib 6); instead of a middle lobe it has the cardiac notch and the lingula , an extension of the superior lobe.","Right lung : three lobes (superior, middle, inferior) separated by the oblique and horizontal fissures; shorter and wider because the right dome is higher, but slightly larger overall."],"dp":[{"h":"Note","t":"Right lung = 3 lobes (oblique + horizontal fissures); left lung = 2 lobes (oblique fissure), with the cardiac notch and lingula ."}]}},"meta":{"1nuy7hi":{"a":"recall","vg":"anat1-respiratory:e0/recall/1"},"cr1p81":{"a":"recall","vg":"anat1-respiratory:e1/recall/1"},"1olllac":{"a":"recall","vg":"anat1-respiratory:e2/recall/1"},"1hi948g":{"a":"recall","vg":"anat1-respiratory:e3/recall/1"},"fzmgf1":{"a":"recall","vg":"anat1-respiratory:e4/recall/1"},"1gkrma7":{"a":"recall","vg":"anat1-respiratory:e5/recall/1"},"dtb3fn":{"a":"recall","vg":"anat1-respiratory:e5/recall/1"},"1co191v":{"a":"recall","vg":"anat1-respiratory:e7/recall/1"},"11qhl8h":{"a":"recall","vg":"anat1-respiratory:e8/recall/1"},"1cw4mhm":{"a":"relationship","vg":"anat1-respiratory:e7/relationship/1"}},"explRev":"8b6933bf2eea"};
